using System.Text;
namespace LSE.AutoCADElectrical.Librarian;
public enum LibraryKind { SchematicSymbol, PanelFootprint, Nameplate, UserCircuit }
public enum IconSource { Render, Thumbnail, ExistingImage, ImageFile, None }
public enum Severity { Error, Warning, Info }
public sealed class AppSettings {
 public string SymbolLibraryFolder{get;set;}=""; public string StockSymbolLibraryFolder{get;set;}=""; public string FootprintLibraryFolder{get;set;}=""; public string StockFootprintLibraryFolder{get;set;}=""; public string UserCircuitsFolder{get;set;}="";
 public string IconMenuFolder{get;set;}=""; public string SchematicMenuFile{get;set;}="ACE_NFPA_MENU.DAT"; public string PanelMenuFile{get;set;}="ACE_PANEL_MENU_NFPA.DAT"; public string ImagesSubfolder{get;set;}="IMAGES";
 public string FootprintLookupPath{get;set;}=""; public string CatalogPath{get;set;}=""; public string LibraryStandardPath{get;set;}=""; public string BackupFolder{get;set;}=""; public string ReferenceProjectPath{get;set;}="";
 public int IconPixels{get;set;}=40; public string DefaultSeries{get;set;}="002"; public bool RegisterFootprintLookup{get;set;}=true; public bool DeepAudit{get;set;} public bool AuditStockEntries{get;set;}
 public string NamingWorkbookPath{get;set;}=""; public string NamingStandardPath{get;set;}=""; public string CatalogBackupFolder{get;set;}=""; public string LsePartColumn{get;set;}="USER1"; public bool OfferCatalogRecord{get;set;}=true; public bool PurchaseDescriptionInUser2{get;set;}=true;
 public List<string> RecentItems{get;set;}=new();
 public string SchematicMenuPath=>Path.Combine(IconMenuFolder,SchematicMenuFile); public string PanelMenuPath=>Path.Combine(IconMenuFolder,PanelMenuFile); public string ImagesFolder=>Path.Combine(IconMenuFolder,ImagesSubfolder);
 public string RootFor(LibraryKind k)=>k switch{LibraryKind.SchematicSymbol=>SymbolLibraryFolder,LibraryKind.UserCircuit=>UserCircuitsFolder,_=>FootprintLibraryFolder};
 public string MenuPathFor(KindRule r)=>r.IsPanel?PanelMenuPath:SchematicMenuPath;
}
public sealed class LibraryStandard { public string Source{get;set;}=""; public string ImagePrefix{get;set;}="IMAGES\\"; public List<string> IgnoreFolders{get;set;}=new(); public Dictionary<string,string> Series{get;set;}=new(StringComparer.OrdinalIgnoreCase); public Dictionary<string,string> SymbolFamilies{get;set;}=new(StringComparer.OrdinalIgnoreCase); public Dictionary<string,KindRule> Kinds{get;set;}=new(StringComparer.OrdinalIgnoreCase); public KindRule Rule(LibraryKind k)=>Kinds.TryGetValue(k.ToString(),out var r)?r:throw new InvalidOperationException("The library standard JSON has no rule for "+k+"."); }
public sealed class KindRule {
 public string DisplayName{get;set;}=""; public string Menu{get;set;}="schematic"; public List<string> Prefixes{get;set;}=new(); public string NamePattern{get;set;}=""; public string NameExample{get;set;}=""; public string NameHelp{get;set;}=""; public int MaxNameLength{get;set;}=64;
 public List<string> RequiredAttributes{get;set;}=new(); public List<string> RecommendedAttributes{get;set;}=new(); public List<string> RequiredAttributePatterns{get;set;}=new(); public List<string> RecommendedAttributePatterns{get;set;}=new(); public List<string> ForbiddenBlocks{get;set;}=new();
 public string ActionTemplate{get;set;}="{PATH}"; public List<string> MenuRootPages{get;set;}=new(); public List<LibraryCategory> Categories{get;set;}=new();
 public bool IsPanel=>Menu.Equals("panel",StringComparison.OrdinalIgnoreCase);
}
public sealed class LibraryCategory { public string Name{get;set;}=""; public string Folder{get;set;}=""; public string MenuPage{get;set;}=""; public override string ToString()=>Name; }
public sealed class LibraryRequest {
 public LibraryKind Kind{get;set;} public string SourcePath{get;set;}=""; public string SourceBlockName{get;set;}=""; public string Name{get;set;}=""; public string TargetFolder{get;set;}=""; public string Description{get;set;}="";
 public string MenuPage{get;set;}=""; public bool CreatePage{get;set;} public string NewPageTitle{get;set;}=""; public string ParentPage{get;set;}=""; public string MenuLabel{get;set;}="";
 public IconSource Icon{get;set;}=IconSource.Render; public string IconPath{get;set;}="";
 public bool RegisterLookup{get;set;} public string LookupManufacturer{get;set;}=""; public string LookupCatalog{get;set;}="";
 public bool AddCatalogRecord{get;set;} public PartNumberRequest? PartNumber{get;set;} public CatalogAddRequest? CatalogRecord{get;set;}
 public string TargetPath=>Path.Combine(TargetFolder,Name+".dwg"); public bool FromCurrentDrawing=>SourceBlockName.Length>0;
 public bool InPlace{get{try{return !FromCurrentDrawing&&SourcePath.Length>0&&Path.GetFullPath(SourcePath).Equals(Path.GetFullPath(TargetPath),StringComparison.OrdinalIgnoreCase);}catch{return false;}}}
}
public sealed class LibraryResult { public LibraryRequest Request{get;set;}=new(); public string DrawingPath{get;set;}=""; public string ImagePath{get;set;}=""; public string MenuPath{get;set;}=""; public string MenuPage{get;set;}=""; public string Report{get;set;}=""; public string PartNumber{get;set;}=""; }
public sealed class AttributeInfo { public string Tag{get;set;}=""; public string Prompt{get;set;}=""; public string Default{get;set;}=""; public bool Invisible{get;set;} public bool Constant{get;set;} }
public sealed class DrawingInfo { public string Path{get;set;}=""; public List<AttributeInfo> Attributes{get;set;}=new(); public List<string> BlockReferences{get;set;}=new(); public int EntityCount{get;set;} public double MinX{get;set;}=double.MaxValue; public double MinY{get;set;}=double.MaxValue; public double MaxX{get;set;}=double.MinValue; public double MaxY{get;set;}=double.MinValue; public bool HasExtents=>MaxX>=MinX&&MaxY>=MinY; public double Width=>HasExtents?MaxX-MinX:0; public double Height=>HasExtents?MaxY-MinY:0; public bool HasThumbnail{get;set;} public string Units{get;set;}=""; public string DwgVersion{get;set;}=""; public bool HasAttribute(string tag)=>Attributes.Any(a=>a.Tag.Equals(tag,StringComparison.OrdinalIgnoreCase)); }
public sealed class IconMenu { public string Path{get;set;}=""; public Encoding Encoding{get;set;}=new UTF8Encoding(true); public string NewLine{get;set;}="\r\n"; public bool TrailingNewLine{get;set;}=true; public List<string> Header{get;set;}=new(); public List<IconMenuPage> Pages{get;set;}=new(); public IconMenuPage? Page(string id)=>Pages.FirstOrDefault(p=>p.Id.Equals(id,StringComparison.OrdinalIgnoreCase)); }
public sealed class IconMenuPage { public string Id{get;set;}=""; public int Number{get;set;}=-1; public string? Layout{get;set;} public List<string> Prelude{get;set;}=new(); public string Title{get;set;}=""; public List<IconMenuEntry> Entries{get;set;}=new(); public override string ToString()=>Id+"  "+Title; }
public sealed class IconMenuEntry { public string Label{get;set;}=""; public string Image{get;set;}=""; public string Action{get;set;}=""; public string? Raw{get;set;} public bool IsEntry=>Raw is null; public string? Submenu=>Action.StartsWith("$S=",StringComparison.OrdinalIgnoreCase)?Action[3..].Trim():null; public override string ToString()=>Raw??$"{Label}|{Image}|{Action}"; }
public sealed class MenuTarget { public string Kind{get;set;}=""; public string Path{get;set;}=""; public string BlockName{get;set;}=""; public string Command{get;set;}=""; }
public sealed class AuditFinding { public Severity Severity{get;set;} public string Area{get;set;}=""; public string Kind{get;set;}=""; public string Path{get;set;}=""; public string Message{get;set;}=""; public string Suggestion{get;set;}=""; public string SeverityText=>Severity.ToString(); }
public sealed class AuditReport { public DateTime Started{get;set;}=DateTime.Now; public List<string> Summary{get;set;}=new(); public List<AuditFinding> Findings{get;set;}=new(); public int Errors=>Findings.Count(f=>f.Severity==Severity.Error); public int Warnings=>Findings.Count(f=>f.Severity==Severity.Warning); public int Infos=>Findings.Count(f=>f.Severity==Severity.Info); }
public sealed class AuditOptions { public bool Deep{get;set;} public bool IncludeStockEntries{get;set;} }
// Part-number naming standard read from the LSE ELECTRICAL PARTS CATALOG MANAGER workbook (or its JSON snapshot).
public sealed class NamingStandard { public string Source{get;set;}=""; public DateTime Loaded{get;set;}=DateTime.Now; public bool FromWorkbook{get;set;} public NamingFormat Format{get;set;}=new(); public List<NamingTab> Tabs{get;set;}=new(); public List<string> SkippedTabs{get;set;}=new(); public Dictionary<string,ManufacturerCode> Manufacturers{get;set;}=new(StringComparer.OrdinalIgnoreCase); public Dictionary<string,List<string>> FamilyHints{get;set;}=new(StringComparer.OrdinalIgnoreCase); public NamingTab? Tab(string name)=>Tabs.FirstOrDefault(t=>t.Name.Equals(name,StringComparison.OrdinalIgnoreCase)); public IEnumerable<string> AllKnownPartNumbers()=>Tabs.SelectMany(t=>t.KnownPartNumbers); }
public sealed class NamingFormat { public int CategoryChars{get;set;}=2; public int ManufacturerChars{get;set;}=3; public int TypeChars{get;set;}=2; public int SequenceChars{get;set;}=7; public int Length=>CategoryChars+ManufacturerChars+TypeChars+SequenceChars; }
public sealed class NamingTab {
 public string Name{get;set;}=""; public string Title{get;set;}=""; public string PartNumberRule{get;set;}=""; public List<string> CategoryCodes{get;set;}=new(); public string CategoryRule{get;set;}=""; public Dictionary<string,string> Types{get;set;}=new(StringComparer.OrdinalIgnoreCase); public Dictionary<string,string> Manufacturers{get;set;}=new(StringComparer.OrdinalIgnoreCase);
 public string DescriptionPattern{get;set;}=""; public string PurchaseDescriptionPattern{get;set;}=""; public List<DescriptionField> DescriptionFields{get;set;}=new(); public List<string> Rules{get;set;}=new(); public List<NamingExample> Examples{get;set;}=new(); public List<string> KnownPartNumbers{get;set;}=new(); public Dictionary<string,string> ManufacturerSpellings{get;set;}=new(StringComparer.OrdinalIgnoreCase);
 public override string ToString()=>Name;
}
