public sealed class NamingExample { public string PartNumber{get;set;}=""; public string Description{get;set;}=""; public string PurchaseDescription{get;set;}=""; }
public sealed class ManufacturerCode { public string Name{get;set;}=""; public string AcadeManufacturer{get;set;}=""; }
public sealed class PartNumberRequest { public string Tab{get;set;}=""; public string Category{get;set;}=""; public string ManufacturerCode{get;set;}=""; public string Type{get;set;}=""; public string ManualPartNumber{get;set;}=""; public string Prefix=>(Category+ManufacturerCode+Type).ToUpperInvariant(); public bool IsManual=>ManualPartNumber.Trim().Length>0; }
public sealed class CatalogAddRequest { public string TableName{get;set;}=""; public string Catalog{get;set;}=""; public string Manufacturer{get;set;}=""; public string Description{get;set;}=""; public string Type{get;set;}=""; public string Rating{get;set;}=""; public string Voltage{get;set;}=""; public string User1{get;set;}=""; public string User2{get;set;}=""; public string User3{get;set;}=""; public string TextValue{get;set;}=""; public string WebLink{get;set;}=""; public string WdBlkNam{get;set;}=""; public string Summary=>$"{TableName} | {Manufacturer} | {Catalog}"; }
public sealed class PartNumberPreview { public string PartNumber{get;set;}=""; public string Prefix{get;set;}=""; public long HighestInCatalog{get;set;} public string HighestInCatalogTable{get;set;}=""; public long HighestInWorkbook{get;set;} public int CatalogMatches{get;set;} public int WorkbookMatches{get;set;} public int CatalogLegacy{get;set;} public int WorkbookLegacy{get;set;} public string Explanation{get;set;}=""; }
public sealed class CatalogAddResult { public string PartNumber{get;set;}=""; public string TableName{get;set;}=""; public string BackupFolder{get;set;}=""; public string Report{get;set;}=""; }
